By default, it's drawn using the "system color" which is color 16. You can copy the below into a text editor, save as a *.js file, and include as a plugin:
Code:
Window_Base.prototype.drawCurrencyValue = function(value, unit, x, y, width) {
    var unitWidth = Math.min(80, this.textWidth(unit));
    this.resetTextColor();
    this.drawText(value, x, y, width - unitWidth - 6, 'right');
// Change the next line
    this.changeTextColor(this.textColor(16));
    this.drawText(unit, x + width - unitWidth, y, unitWidth, 'right');
};
Change the 16 in parentheses to be whichever color you want.

